CREATE PROCEDURE sp_level(IN score INT, OUT lv VARCHAR(10))
BEGIN
  IF score >= 85 THEN SET lv = '优秀';
  ELSEIF score >= 60 THEN SET lv = '合格';
  ELSE SET lv = '不合格';
  END IF;
END $$
DELIMITER ;
