CREATE FUNCTION fn_avg_grade(sid CHAR(10))
  RETURNS DECIMAL(5,2)
BEGIN
  DECLARE avg_g DECIMAL(5,2);
  SELECT AVG(Grade) INTO avg_g FROM SC WHERE Sno = sid;
